parameters.text:
={{
  (() => {
    // 1. Извлекаем контекст из активного якорного узла
    const ctx = $('[DB] Загрузить черновик карусели').isExecuted
      ? $('[DB] Загрузить черновик карусели').item.json
      : $('[DB] Загрузить контекст и токен').item.json;

    // 2. Словари нормализации названий
    const platformNames = {
      instagram: 'Instagram',
      vk: 'ВКонтакте',
      youtube: 'YouTube',
      telegram: 'Telegram'
    };

    const formatNames = {
      reels: 'Reels',
      feed_post: 'поста в ленту',
      carousel: 'карусели',
      shorts: 'Shorts'
    };

    const targetPlatform = ctx?.draft_data?.target_platform;
    const targetFormat = ctx?.draft_data?.target_format;

    const platform = platformNames[targetPlatform] || 'соцсеть';
    const format = formatNames[targetFormat] || 'материала';

    // 3. Определение причины сбоя
    let reason = 'Произошла непредвиденная ошибка на стороне сервиса.';

    if ($json.status_code === 'ERROR') {
      reason = 'Серверы площадки отклонили медиафайл (проверьте формат, пропорции или размер).';
    } else if ($json.status_code === 'IN_PROGRESS') {
      reason = 'Превышено время ожидания обработки на серверах площадки (таймаут кодирования).';
    } else if ($json.error?.message) {
      reason = $json.error.message;
    } else if ($json.errorMessage) {
      reason = $json.errorMessage;
    }

    return `❌ Не удалось опубликовать ${format} в ${platform}.\n\nПричина: ${reason}`;
  })()
}}

=🎞 Сборка карусели Instagram ({{ $('[DB] Актуализировать счетчик карусели').item.json.items_count }}/10)

Состав публикации:
{{ ($('[DB] Актуализировать счетчик карусели').item.json.draft_data?.items || []).map((item, idx) => `${idx + 1}. ${item.type === 'photo' ? 'Фотография 🖼' : 'Видеоролик 🎬'}`).join('\n') }}

📝 Описание: {{ $('[DB] Актуализировать счетчик карусели').item.json.current_caption ? `«${$('[DB] Актуализировать счетчик карусели').item.json.current_caption}»` : 'отсутствует (будет опубликовано без текста)' }}

{{
  (() => {
    const count = $('[DB] Актуализировать счетчик карусели').item.json.items_count || 0;
    if (count === 0) {
      return '⚠️ Для публикации карусели добавьте минимум 2 файла (фотографии или видео).';
    } else if (count === 1) {
      return '⚠️ Для публикации карусели добавьте ещё минимум 1 файл.';
    } else {
      return '✅ Карусель готова к публикации!';
    }
  })()
}}

parameters.jsCode:
const inputItems = $input.all();
if (!inputItems.length) return [];

const item = inputItems[0].json;
const slides = item.draft_data?.items || [];

return slides.map((slide, index) => ({
  json: {
    file_id: slide.file_id,
    type: slide.type,
    slide_index: index + 1,
    total_slides: slides.length
  }
}));

const allChildResponses = $input.all();

// Извлекаем реальные ID созданных контейнеров
const childContainerIds = allChildResponses
  .map(item => item.json.id)
  .filter(id => Boolean(id));

return [{
  json: {
    children: childContainerIds.join(','), // Формат: "1801...,1802...,1803..."
    items_count: childContainerIds.length
  }
}];

