const items = $input.all();

// Проверяем статус каждого слайда
const allFinished = items.every(item => item.json.status_code === 'FINISHED');
const hasError = items.some(item => item.json.status_code === 'ERROR');
const finishedCount = items.filter(item => item.json.status_code === 'FINISHED').length;

return [{
  json: {
    status: hasError ? 'ERROR' : (allFinished ? 'FINISHED' : 'IN_PROGRESS'),
    allFinished: allFinished,
    finishedCount: finishedCount,
    totalCount: items.length,
    // Собираем строку ID через запятую для Meta Parent Carousel
    children: items.map(item => item.json.id).join(','),
    // Сохраняем массив ID на случай повторного круга опроса
    childIds: items.map(item => item.json.id)
  }
}];

const items = $input.all();
if (!items.length) return [];

const ids = items[0].json.childIds || [];
return ids.map(id => ({ json: { id } }));
